pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1 ether + 1, 10000 ether);

        Log log = Log(c.TransferLog());
        (, , , uint256 lenBefore) = (address(0), "", 0, log.History(0) == (address(0), "", 0, 0) ? (uint256(0)) : uint256(0));
        lenBefore = _historyLen(log);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        uint256 lenAfter = _historyLen(log);
        assertTrue(lenAfter == lenBefore + 1);
    }

    function _historyLen(Log log) internal returns (uint256) {
        // History is a public array of structs; probe length by incrementing index until revert.
        uint256 i = 0;
        while (true) {
            try log.History(i) returns (C.Log.Message memory) {
                i++;
            } catch {
                return i;
            }
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public { log = new Log(); c = new C(address(log)); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1 ether + 1, 10000 ether);

        uint256 lenBefore = log.History();

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        uint256 lenAfter = log.History();

        bool recorded = false;
        for (uint256 i = lenBefore; i < lenAfter; i++) {
            (address sender, , uint256 val, ) = log.History(i);
            if (sender == actor && val == amount) {
                recorded = true;
                break;
            }
        }

        assertTrue(recorded, "deposit must be recorded in the Log History");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 am, uint256 am2) public {
        vm.assume(am > 1 ether);
        bound(am, 1 ether + 1, 2 ether);
        vm.assume(am2 > 0);

        Reentrant attacker = new Reentrant{value: 3 * am}(c);
        bool ok;
        try attacker.attack(am, am2) { ok = true; } catch { ok = false; }

        // General rule: a CashOut of _am with _am <= caller balance must not revert
        // (deduction happens before the external call, so reentrant withdrawals
        // see the already-reduced balance and cannot corrupt it).
        assertTrue(ok);
    }
}

contract Reentrant {
    C c;
    bool reentered;

    constructor(C _c) payable {
        c = _c;
    }

    function attack(uint256 am, uint256 am2) external {
        c.Deposit{value: am}();
        c.CashOut(am);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            (bool s, ) = address(c).call(
                abi.encodeWithSelector(c.CashOut.selector, msg.value)
            );
            s; // ignore result
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(uint v) public {
        require(v > 1 ether);
        require(address(this).balance >= v);
        uint bal0 = c.balances(address(this));
        if (bal0 > 0) {
            c.CashOut(bal0);
        }
        c.Deposit{value: v}();
        assert(c.balances(address(this)) == v);
    }

    receive() external payable {}
    fallback() external payable {}
}
